        _ = &overlapped;
        while (true) {
            const rc = w.kernel32.GetQueuedCompletionStatus(self.iocp, (&nbytes), (&key), (&overlapped), @intFromEnum(timeout));
            if ((rc == 0)) {
                const e = w.kernel32.GetLastError();
