                    return .{ .result = null };
                } else {
                    _ = log("GetQueuedCompletionStatus failed: {s}", .{ @tagName(e) });
                    return .{ .err = .{ .errno = @intFromEnum(((bun.sys.SystemErrno.init(e)) orelse (bun.sys.SystemErrno.EINVAL))), .syscall = .watch } };
                }
