                if ((ptr != (&self.watcher.overlapped))) {
                    continue;
                }
                if ((nbytes == 0)) {
                    _ = log("shutdown notification in WindowsWatcher.next", .{});
                    return .{ .err = .{ .errno = @intFromEnum(bun.sys.SystemErrno.ESHUTDOWN), .syscall = .watch } };
                }
