            } else {
                _ = log("GetQueuedCompletionStatus returned no overlapped event", .{});
                return .{ .err = .{ .errno = @truncate(@intFromEnum(bun.sys.E.INVAL)), .syscall = .watch } };
            }
        }
}

pub fn stop(self: *WindowsWatcher) void {
        _ = w.CloseHandle(self.watcher.dirHandle);
        _ = w.CloseHandle(self.iocp);
}

pub fn watchLoopCycle(watcher: *bun.Watcher) bun.sys.Maybe(void) {
        const buf = (&watcher.platform.buf);
        const base_idx = watcher.platform.base_idx;
        var event_id: usize = 0;
        _ = &event_id;
        var timeout = Timeout.infinite;
        _ = &timeout;
        while (true) {
            var iter = (switch (watcher.platform.next(timeout)) {
.err => |e| {
return .{ .err = e };
},
.result => |it| ((it) orelse break),
});
            _ = &iter;
            timeout = Timeout.none;
            const item_paths = watcher.watchlist.items(.file_path);
            _ = log("number of watched items: {d}", .{ item_paths.len });
            while (iter.next()) |event| {
                const convert_res = bun.strings.copyUTF16IntoUTF8(buf[base_idx..], event.filename);
                const eventpath = buf[0..(base_idx + convert_res.written)];
                _ = log("watcher update event: (filename: {s}, action: {s}", .{ eventpath, @tagName(event.action) });
                {
                    var item_idx: i32 = 0;
                    _ = &item_idx;
                    const __end_0 = item_paths.len;
                    while (item_idx < __end_0) : (item_idx += 1) {
                        const path = item_paths[@as(usize, @intCast(item_idx))];
                        const rel = bun.path.isParentOrEqual(path, eventpath);
                        _ = log("checking path: {s} = .{s}", .{ path, @tagName(rel) });
                        if ((rel == .unrelated)) {
                            continue;
                        }
                        if ((event_id >= watcher.watch_events.len)) {
                            switch (processWatchEventBatch(watcher, event_id)) {
.err => |e| {
return .{ .err = e };
},
.result => {

},
}
                            event_id = 0;
                        }
                        watcher.watch_events[cp_cast_int(usize, event_id)] = createWatchEvent(event, @truncate(item_idx));
                        event_id = (event_id + 1);
                    }
                }
            }
        }
        if ((event_id > 0)) {
            switch (processWatchEventBatch(watcher, event_id)) {
.err => |e| {
return .{ .err = e };
},
.result => {

},
}
        }
        return .success;
}

pub fn processWatchEventBatch(watcher: *bun.Watcher, event_count: usize) bun.sys.Maybe(void) {
        if ((event_count == 0)) {
            return .success;
        }
        var all_events = watcher.watch_events[0..event_count];
        _ = &all_events;
        _ = std.sort.pdq(WatchEvent, all_events, .{}, WatchEvent.sortByIndex);
        var last_event_index: usize = 0;
        _ = &last_event_index;
        var last_event_id: u32 = std.math.maxInt(u32);
        _ = &last_event_id;
        {
            var i: i32 = 0;
            _ = &i;
            const __end_1 = all_events.len;
            while (i < __end_1) : (i += 1) {
                if ((all_events[@as(usize, @intCast(i))].index == last_event_id)) {
                    _ = all_events[@as(usize, @intCast(last_event_index))].merge(all_events[@as(usize, @intCast(i))]);
                    continue;
                }
                last_event_index = i;
                last_event_id = all_events[@as(usize, @intCast(i))].index;
            }
        }
        if ((all_events.len == 0)) {
            return .success;
        }
        all_events = all_events[0..(last_event_index + 1)];
        _ = log("calling onFileUpdate (all_events.len = {d})", .{ all_events.len });
        _ = watcher.writeTraceEvents(all_events, watcher.changed_filepaths[0..(last_event_index + 1)]);
        _ = watcher.onFileUpdate(watcher.ctx, all_events, watcher.changed_filepaths[0..(last_event_index + 1)], watcher.watchlist);
        return .success;
}

pub fn createWatchEvent(event: FileEvent, index: WatchItemIndex) WatchEvent {
        return .{ .op = .{ .delete = (event.action == .Removed), .rename = (event.action == .RenamedOld), .write = (event.action == .Modified) }, .index = index };
}
